  adiciona-borda(
    overlay-align("middle", "bottom",
      text(naipe, 14, "black"),
      overlay-align("middle", "top",
        text(num-to-string(valor), 24, "black"),
        fundo-com-icone(seleciona-icone-naipe(naipe)))))
end


